import json, sys

def text_of_content(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for c in content:
            if not isinstance(c, dict):
                continue
            t = c.get('type')
            if t == 'text':
                parts.append(c.get('text',''))
            elif t == 'tool_use':
                name = c.get('name')
                inp = c.get('input', {})
                # shorten input
                inp_s = json.dumps(inp)[:300]
                parts.append(f"[TOOL_USE {name}] {inp_s}")
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    sub = []
                    for cc in cont:
                        if isinstance(cc, dict) and cc.get('type')=='text':
                            sub.append(cc.get('text',''))
                    s = ' '.join(sub)
                else:
                    s = str(cont)
                is_err = c.get('is_error')
                tag = "ERROR" if is_err else "OK"
                parts.append(f"[TOOL_RESULT {tag}] {s[:400]}")
        return '\n'.join(parts)
    return str(content)

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            typ = d.get('type')
            ts = d.get('timestamp','')
            if typ == 'queue-operation':
                op = d.get('operation')
                content = d.get('content','')
                if content:
                    print(f"{ts} QUEUE-{op}: {content[:500]}")
                continue
            if typ == 'attachment':
                continue  # skip noisy tool-listing deltas
            if typ == 'summary':
                continue
            msg = d.get('message')
            if not msg:
                continue
            role = msg.get('role')
            content = msg.get('content')
            text = text_of_content(content)
            if not text.strip():
                continue
            print(f"{ts} {role.upper()}: {text[:600]}")

if __name__ == '__main__':
    main(sys.argv[1])

