1	import 'dart:typed_data';
2	import 'dart:ui' as ui;
3	
4	import 'package:flutter/material.dart';
5	import 'package:flutter/rendering.dart';
6	import 'package:flutter_test/flutter_test.dart';
7	import 'package:setlist_ui/testing.dart';
8	
9	/// The assurance behind [loadProductFonts]: with the product's fonts loaded,
10	/// two strings that differ only in a character — not in length — must render
11	/// differently.
12	///
13	/// This is the test that keeps the gallery honest. Without it the harness can
14	/// regress to the stub font and every golden keeps passing while proving only
15	/// that the text is the right *length*; the spec pins exact copy at more than a
16	/// dozen leaves, and all of them would silently stop being checked. Watched it
17	/// fail with the fonts unloaded: the two renders below came back identical.
18	void main() {
19	  setUpAll(loadProductFonts);
20	
21	  testWidgets('same-length copy changes are visible in a render', (tester) async {
22	    final stand = await _render(tester, 'THE STAND');
23	    final stane = await _render(tester, 'THE STANE');
24	
25	    // Same character count and the same style, so the layout box is identical:
26	    // a difference in the pixels can only be the glyphs themselves.
27	    expect(stand.width, stane.width);
28	    expect(stand.height, stane.height);
29	    expect(
30	      stand.pixels,
31	      isNot(equals(stane.pixels)),
32	      reason: 'THE STAND and THE STANE rendered identically — the renderer is '
33	          'drawing boxes, not glyphs, so no golden can see wrong copy',
34	    );
35	  });
36	
37	}
38	
39	final _boundary = GlobalKey();
40	
41	class _Render {
